//! Executable entry-point bridging for Nova packages.
//!
//! A class's `static fn main` is an ordinary static method. It becomes the
//! process entry point **only** if the root package explicitly selects it with
//! `[package] main = "Class::method"` in Nova.toml.
//!
//! This does not infer a process entry from annotations: libraries cannot
//! silently select executables. However, when the manifest explicitly chooses
//! `DB::main` for a `@BootApplication` class, the selected method may be
//! generated by that decorator later during surface lowering.
use crate::ast::{self, Expr, Item, Stmt, TypeRef};

fn join(ns: &str, name: &str) -> String {
    if ns.is_empty() { name.to_owned() } else { format!("{ns}::{name}") }
}

fn methods<'a>(items: &'a [Item], namespace: &str, target: &str, name: &str, found: &mut Vec<&'a ast::Function>) {
    for item in items {
        match item {
            Item::Public(inner) => methods(std::slice::from_ref(inner.as_ref()), namespace, target, name, found),
            Item::Namespace { name: ns, items } => methods(items, &join(namespace, ns), target, name, found),
            Item::Impl(block) => {
                let TypeRef::Named(owner) = &block.target else { continue };
                let qualified = if owner.contains("::") { owner.clone() } else { join(namespace, owner) };
                if qualified == target {
                    found.extend(block.methods.iter().filter(|method| method.name == name));
                }
            }
            _ => {}
        }
    }
}

/// `@BootApplication` generates `static fn main() -> i32` during procedural
/// expansion (in surface lowering). Package loading runs *before* that pass,
/// so the method cannot be found in the linked, unexpanded AST yet.
///
/// This is a narrowly scoped deferred entry: it is permitted only for
/// `[package] main = "Class::main"` on the annotated class. Other missing
/// methods are still errors, and the generated method is fully typechecked
/// in the normal surface/HIR pipeline before emitting executable code.
fn deferred_boot_main(items: &[Item], ns: &str, owner: &str) -> bool {
    items.iter().any(|item| match item {
        Item::Public(inner) => deferred_boot_main(std::slice::from_ref(inner.as_ref()), ns, owner),
        Item::Namespace { name, items } => deferred_boot_main(items, &join(ns, name), owner),
        Item::Struct(decl) => {
            decl.is_class
                && join(ns, &decl.name) == owner
                && decl.attributes.iter().any(|attr| {
                    matches!(attr.name.as_str(), "BootApplication" | "NB::BootApplication")
                })
        }
        _ => false,
    })
}

fn deferred_sdlef_main(items: &[Item], ns: &str, owner: &str) -> bool {
    items.iter().any(|item| match item {
        Item::Public(inner) => deferred_sdlef_main(std::slice::from_ref(inner.as_ref()), ns, owner),
        Item::Namespace { name, items } => deferred_sdlef_main(items, &join(ns, name), owner),
        Item::Struct(decl) => {
            decl.is_class
                && join(ns, &decl.name) == owner
                && decl.attributes.iter().any(|attr| attr.name == "sdlefGame")
        }
        _ => false,
    })
}

fn deferred_sdlef_2d_main(items: &[Item], ns: &str, owner: &str) -> bool {
    items.iter().any(|item| match item {
        Item::Public(inner) => deferred_sdlef_2d_main(std::slice::from_ref(inner.as_ref()), ns, owner),
        Item::Namespace { name, items } => deferred_sdlef_2d_main(items, &join(ns, name), owner),
        Item::Struct(decl) => {
            decl.is_class
                && join(ns, &decl.name) == owner
                && decl.attributes.iter().any(|attr| attr.name == "sdlefGame2D")
        }
        _ => false,
    })
}

fn global_main(items: &[Item]) -> bool {
    items.iter().any(|item| match item {
        Item::Function(f) => f.name == "main",
        Item::Public(inner) => matches!(inner.as_ref(), Item::Function(f) if f.name == "main"),
        _ => false,
    })
}

/// Build the platform ABI bridge for the method explicitly selected in Nova.toml.
/// Package loading calls this on the linked root package; ordinary .nova files
/// and dependencies never get an entry point inferred from a static method.
pub fn generate(program: &ast::Program, selected: &str) -> Result<ast::Program, String> {
    let (owner, method_name) = selected.rsplit_once("::")
        .ok_or_else(|| format!("error[NOVA-ENTRY001]: package main '{selected}' must name a static method as 'Class::method'"))?;
    if owner.is_empty() || method_name.is_empty() || selected.split("::").any(|part| part.is_empty()) {
        return Err(format!("error[NOVA-ENTRY001]: invalid package main '{selected}'; expected 'Class::method'"));
    }
    if global_main(&program.items) {
        return Err(format!("error[NOVA-ENTRY003]: package main '{selected}' conflicts with global fn main; choose one entry point"));
    }
    let mut found = Vec::new();
    methods(&program.items, "", owner, method_name, &mut found);
    let generated_by_boot = found.is_empty()
        && method_name == "main"
        && deferred_boot_main(&program.items, "", owner);
    let generated_by_sdlef = found.is_empty()
        && method_name == "main"
        && deferred_sdlef_main(&program.items, "", owner);
    let generated_by_sdlef_2d = found.is_empty()
        && method_name == "main"
        && deferred_sdlef_2d_main(&program.items, "", owner);
    if found.len() != 1 && !generated_by_boot && !generated_by_sdlef && !generated_by_sdlef_2d {
        return Err(format!("error[NOVA-ENTRY004]: package main '{selected}' must resolve to exactly one method in an impl block; found {}", found.len()));
    }
    // Explicit entries are checked here, as before. The @BootApplication
    // entry is synthesized later; ordinary typechecking checks its signature
    // and the reference from the global ABI bridge after expansion.
    if let Some(method) = found.first() {
        if !method.attributes.iter().any(|a| a.name == "static") || !method.generics.is_empty() || !method.concept_bounds.is_empty() || method.variadic {
            return Err(format!("error[NOVA-ENTRY005]: package main '{selected}' must be a non-generic static method"));
        }
        if method.result != TypeRef::Named("i32".into()) {
            return Err(format!("error[NOVA-ENTRY006]: package main '{selected}' must return i32"));
        }
        if !method.params.is_empty() {
            return Err(format!("error[NOVA-ENTRY007]: package main '{selected}' must have no parameters; use std::old::arg for process arguments"));
        }
    }
    let mut result = program.clone();
    if generated_by_sdlef || generated_by_sdlef_2d {
        let owner_type = TypeRef::Named(owner.to_owned());
        let callback = |name: &str| Expr::FunctionRef(format!("{owner}::{name}"));
        let run = Expr::GenericCall(
            if generated_by_sdlef_2d { "sdlef::application::run_2d".into() } else { "sdlef::application::run".into() },
            vec![owner_type],
            vec![
                Expr::Call(format!("{owner}::new"), vec![]),
                callback("start"),
                callback("key"),
                callback("update"),
                callback("render"),
                callback("stop"),
                Expr::Str("\"SDLEF Application\"".into()),
                Expr::Int("800".into()),
                Expr::Int("600".into()),
                Expr::Int("16".into()),
            ],
        );
        result.items.push(Item::Impl(ast::Impl {
            target: TypeRef::Named(owner.to_owned()),
            generics: vec![],
            trait_name: None,
            associated_types: vec![],
            methods: vec![ast::Function {
                mode: ast::FunctionMode::Normal,
                name: "main".into(),
                generics: vec![],
                concept_bounds: vec![],
                params: vec![],
                variadic: false,
                result: TypeRef::Named("i32".into()),
                body: vec![Stmt::Return(Some(run))],
                is_virtual: false,
                is_override: false,
                attributes: vec![ast::Attribute { name: "static".into(), args: vec![] }],
            }],
        }));
    }
    result.items.push(Item::Function(ast::Function {
        mode: ast::FunctionMode::Normal,
        name: "main".into(),
        generics: vec![],
        concept_bounds: vec![],
        params: vec![],
        variadic: false,
        result: TypeRef::Named("i32".into()),
        body: vec![Stmt::Return(Some(Expr::Call(selected.to_owned(), vec![])))],
        is_virtual: false,
        is_override: false,
        attributes: vec![],
    }));
    Ok(result)
}
